package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.util.reflection.FieldUtils;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_optimize_TriageGen0Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private UnivariateRealFunction mockFunction;
    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    private final int starts = 3;
    private final int maxIterations = 100;
    private final int maxEvaluations = 100;

    @Before
    public void setUp() throws Exception {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = mock(RandomGenerator.class);
        mockFunction = mock(UnivariateRealFunction.class);

        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, starts, mockGenerator);

        // Use reflection to set private fields required for the logic
        FieldUtils.writeField(multiStartOptimizer, "maxIterations", maxIterations, true);
        FieldUtils.writeField(multiStartOptimizer, "maxEvaluations", maxEvaluations, true);
    }

    @Test
    public void testOptimize_SuccessMaximize() throws Exception {
        // Setup: 3 starts. 
        // Start 0: returns x=1.0, y=10.0
        // Start 1: returns x=2.0, y=20.0
        // Start 2: returns x=3.0, y=5.0
        // Goal: MAXIMIZE -> Should return 2.0

        when(mockGenerator.nextDouble()).thenReturn(0.5);

        when(mockOptimizer.optimize(eq(mockFunction), eq(GoalType.MAXIMIZE), anyDouble(), anyDouble()))
                .thenReturn(1.0, 2.0, 3.0);

        when(mockOptimizer.getFunctionValue())
                .thenReturn(10.0, 20.0, 5.0);

        when(mockOptimizer.getIterationCount()).thenReturn(1, 1, 1);
        when(mockOptimizer.getEvaluations()).thenReturn(1, 1, 1);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0, 10);

        assertEquals(2.0, result, 1e-10);
        assertEquals(20.0, multiStartOptimizer.getOptimaValues()[0], 1e-10);
    }

    @Test
    public void testOptimize_SuccessMinimize() throws Exception {
        // Setup: 3 starts.
        // Start 0: x=1, y=10
        // Start 1: x=2, y=2
        // Start 2: x=3, y=5
        // Goal: MINIMIZE -> Should return 2.0

        when(mockGenerator.nextDouble()).thenReturn(0.5);

        when(mockOptimizer.optimize(eq(mockFunction), eq(GoalType.MINIMIZE), anyDouble(), anyDouble()))
                .thenReturn(1.0, 2.0, 3.0);

        when(mockOptimizer.getFunctionValue())
                .thenReturn(10.0, 2.0, 5.0);

        when(mockOptimizer.getIterationCount()).thenReturn(1, 1, 1);
        when(mockOptimizer.getEvaluations()).thenReturn(1, 1, 1);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MINIMIZE, 0, 10);

        assertEquals(2.0, result, 1e-10);
    }

    @Test(expected = OptimizationException.class)
    public void testOptimize_AllFail() throws Exception {
        // All starts throw exception
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble()))
                .thenThrow(new ConvergenceException("Fail"));

        multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0, 10);
    }

    @Test
    public void testOptimize_PartialFailure() throws Exception {
        // Start 0: Success (x=1, y=10)
        // Start 1: ConvergenceException (NaN)
        // Start 2: FunctionEvaluationException (NaN)

        when(mockGenerator.nextDouble()).thenReturn(0.5);

        when(mockOptimizer.optimize(eq(mockFunction), eq(GoalType.MAXIMIZE), anyDouble(), anyDouble()))
                .thenReturn(1.0)
                .thenThrow(new ConvergenceException("Fail"))
                .thenThrow(new FunctionEvaluationException("Fail"));

        when(mockOptimizer.getFunctionValue()).thenReturn(10.0);
        when(mockOptimizer.getIterationCount()).thenReturn(1, 0, 0);
        when(mockOptimizer.getEvaluations()).thenReturn(1, 0, 0);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0, 10);

        assertEquals(1.0, result, 1e-10);
        // Verify NaNs are moved to the end
        double[] optima = multiStartOptimizer.getOptima();
        assertEquals(1.0, optima[0], 1e-10);
        assertEquals(Double.NaN, optima[2], 0.0);
    }

    @Test
    public void testOptimize_SortingLogicComplex() throws Exception {
        // Test the insertion sort logic specifically
        // Goal: MAXIMIZE
        // Inputs (out of order): (x=1, y=10), (x=2, y=30), (x=3, y=20)
        // Expected sorted: x=2 (y=30), x=3 (y=20), x=1 (y=10)

        when(mockGenerator.nextDouble()).thenReturn(0.1);
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble()))
                .thenReturn(1.0, 2.0, 3.0);
        when(mockOptimizer.getFunctionValue())
                .thenReturn(10.0, 30.0, 20.0);
        when(mockOptimizer.getIterationCount()).thenReturn(1, 1, 1);
        when(mockOptimizer.getEvaluations()).thenReturn(1, 1, 1);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0, 10);

        assertEquals(2.0, result, 1e-10);
        double[] optima = multiStartOptimizer.getOptima();
        assertEquals(2.0, optima[0], 1e-10);
        assertEquals(3.0, optima[1], 1e-10);
        assertEquals(1.0, optima[2], 1e-10);
    }

    @Test
    public void testOptimize_SingleStart() throws Exception {
        // Set starts to 1 via reflection for this specific test
        FieldUtils.writeField(multiStartOptimizer, "starts", 1, true);

        when(mockGenerator.nextDouble()).thenReturn(0.5);
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble())).thenReturn(5.0);
        when(mockOptimizer.getFunctionValue()).thenReturn(100.0);
        when(mockOptimizer.getIterationCount()).thenReturn(5);
        when(mockOptimizer.getEvaluations()).thenReturn(5);

        double result = multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0, 10);
        assertEquals(5.0, result, 1e-10);
    }

    @Test
    public void testOptimize_BoundCalculation() throws Exception {
        // Test that bound1 and bound2 are calculated correctly for i=0 vs i > 0
        // i=0: bound1=min, bound2=max
        // i=1: bound1=min + rand*(max-min), bound2=min + rand*(max-min)

        FieldUtils.writeField(multiStartOptimizer, "starts", 2, true);
        when(mockGenerator.nextDouble()).thenReturn(0.5); // mid point

        multiStartOptimizer.optimize(mockFunction, GoalType.MAXIMIZE, 0, 100);

        // For i=0: min=0, max=100
        verify(mockOptimizer).optimize(eq(mockFunction), eq(GoalType.MAXIMIZE), eq(0.0), eq(100.0));

        // For i=1: rand=0.5, min=0, max=100 -> bound = 0 + 0.5 * 100 = 50
        // Since bound1 and bound2 are both 50, min(50,50)=50, max(50,50)=50
        verify(mockOptimizer).optimize(eq(mockFunction), eq(GoalType.MAXIMIZE), eq(50.0), eq(50.0));
    }
}
